for k,v in {'page':0,'hist':None,'storm':0,'reviewed':0,'funding':0,'inspect':False,'audience_choice':'No action','presentation_mode':True,'agent_step':0,'files_pulled':0,'selected_file':0,'nav_hidden':False}.items(): st.session_state.setdefault(k,v)
