 st.session_state.presentation_mode=st.toggle('Presentation Mode',value=st.session_state.presentation_mode);st.markdown(f'**Act {st.session_state.page+1} of {len(PAGES)}**');st.caption(PAGES[st.session_state.page]);a,b=st.columns(2)
 if a.button('←',use_container_width=True):st.session_state.page=max(0,st.session_state.page-1);st.rerun()
